import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long MOD = 1000000007L;
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 0) {
            System.out.println(powMod(p, p - 1, MOD));
        } else if (k == 1) {
            System.out.println(powMod(p, p, MOD));
        } else {
            long[] cycle = new long[p]; // maximum size is p, but we will track actual size separately
            int cycleLength = 0;
            cycle[cycleLength++] = 1;
            while (true) {
                long nextVal = (cycle[cycleLength - 1] * k) % p;
                boolean found = false;
                for (int i = 0; i < cycleLength; i++) {
                    if (cycle[i] == nextVal) {
                        found = true;
                        break;
                    }
                }
                if (found) {
                    break;
                }
                cycle[cycleLength++] = nextVal;
            }
            long exponent = (p - 1) / cycleLength;
            System.out.println(powMod(p, exponent, MOD));
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1L;
        long curr = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * curr) % mod;
            }
            curr = (curr * curr) % mod;
            exp >>= 1;
        }
        return result;
    }
}
